#iframe-example {
  border: none;
  width: 100%;
  height: 500px;
}

.help-centre {
  background-color: #f0f0f0;
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 10px;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}
```
